code='''def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]
    # The 30x30 view is cropped from a 32-wide symmetric pattern, so the
    # reflected index is 31-i (not n-1-i). Diagonal symmetry also holds.
    def orbit(r, c):
        return {(r, c), (31 - r, c), (r, 31 - c),
                (31 - r, 31 - c), (c, r),
                (31 - c, r), (c, 31 - r),
                (31 - c, 31 - r)}
    for r in range(n):
        for c in range(n):
            if out[r][c] == 6:
                vals = {out[a][b] for a, b in orbit(r, c)
                        if 0 <= a < n and 0 <= b < n and out[a][b] != 6}
                if vals:
                    value = vals.pop()
                    for a, b in orbit(r, c):
                        if 0 <= a < n and 0 <= b < n and out[a][b] == 6:
                            out[a][b] = value
    return out
'''
